<?php
require_once 'functions.php';require_admin();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='toggle'){$uid=(int)($_POST['user_id']??0);if($uid===(int)current_user()['user_id'])$err='You cannot deactivate the account you are currently using.';else{$q=$pdo->prepare("UPDATE users SET status=IF(status='Active','Inactive','Active') WHERE user_id=?");$q->execute([$uid]);if($q->rowCount()){log_action($pdo,'Changed account status','User Management','User ID '.$uid);$msg='Account status updated.';}else $err='Account not found or status unchanged.';}}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='add_student'){$num=trim($_POST['student_number']??'');$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');$course=trim($_POST['course']??'BSIT');$year=trim($_POST['year_level']??'1st Year');$section=trim($_POST['section']??'A');$email=trim($_POST['email']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';if(!$num||!$first||!$last||!$username||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10)$err='Complete all fields with a valid email. Password must be at least 10 characters.';else{try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO students (student_number,first_name,last_name,course,year_level,section) VALUES (?,?,?,?,?,?)');$q->execute([$num,$first,$last,$course,$year,$section]);$sid=(int)$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO users (username,password_hash,role,student_id,full_name,email,status) VALUES (?,?,'Student',?,?,?,'Active')");$q->execute([$username,password_hash($password,PASSWORD_DEFAULT),$sid,$first.' '.$last,$email]);$pdo->commit();log_action($pdo,'Created student account','User Management','Student number '.$num);$msg='Student and login account created.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err='Could not create account. Student number or username may already exist.';}}}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='add_admin'){$username=trim($_POST['admin_username']??'');$name=trim($_POST['admin_name']??'');$password=$_POST['admin_password']??'';$email=trim($_POST['admin_email']??'');if(!$username||!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10)$err='Enter username, full name, a valid email, and password of at least 10 characters.';else{try{$q=$pdo->prepare("INSERT INTO users (username,password_hash,role,student_id,full_name,email,status) VALUES (?,?,'Admin',NULL,?,?,'Active')");$q->execute([$username,password_hash($password,PASSWORD_DEFAULT),$name,$email]);log_action($pdo,'Created admin account','User Management','Username '.$username);$msg='Admin account created.';}catch(Throwable $e){$err='Could not create account. Username may already exist.';}}}
$rows=$pdo->query("SELECT s.*,u.user_id,u.username,u.status FROM students s LEFT JOIN users u ON u.student_id=s.student_id ORDER BY s.student_id DESC")->fetchAll();$admins=$pdo->query("SELECT user_id,username,full_name,status FROM users WHERE role='Admin' ORDER BY user_id")->fetchAll();page_header('User Management');?>
<h1>User Management</h1><p class="muted">Create student profiles and OSA staff accounts, and activate/deactivate accounts.</p><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>
<section class="panel form-panel"><h2>Add Student</h2><form method="post" class="grid-form"><input type="hidden" name="action" value="add_student"><label>Student Number<input name="student_number" required></label><label>Username<input name="username" required></label><label>First Name<input name="first_name" required></label><label>Last Name<input name="last_name" required></label><label>Registered Email<input type="email" name="email" required autocomplete="email"></label><label>Course<input name="course" value="BSIT" required></label><label>Year Level<select name="year_level"><option>1st Year</option><option>2nd Year</option><option>3rd Year</option><option>4th Year</option></select></label><label>Section<input name="section" value="A" required></label><label>Temporary Password<input type="password" name="password" minlength="10" required></label><div><button class="btn primary">Create Student</button></div></form></section>
<section class="panel form-panel"><h2>Add Admin / OSA Staff Account</h2><form method="post"><input type="hidden" name="action" value="add_admin"><label>Full Name</label><input name="admin_name" required><label>Registered Email</label><input type="email" name="admin_email" required autocomplete="email"><label>Username</label><input name="admin_username" required><label>Password (minimum 10 characters)</label><input type="password" name="admin_password" minlength="10" required><p><button class="btn primary">Create Admin Account</button></p></form></section>
<section class="panel"><h2>Student Accounts</h2><div class="table-wrap"><table><thead><tr><th>Student No.</th><th>Name</th><th>Course</th><th>Year</th><th>Section</th><th>Username</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['student_number'])?></td><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['course'])?></td><td><?=e($r['year_level'])?></td><td><?=e($r['section'])?></td><td><?=e($r['username']??'No login')?></td><td><?=e($r['status']??'N/A')?></td><td><?php if($r['user_id']):?><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="user_id" value="<?=$r['user_id']?>"><button class="btn"><?=($r['status']==='Active')?'Deactivate':'Activate'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Admin / OSA Staff Accounts</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($admins as $a):?><tr><td><?=e($a['full_name'])?></td><td><?=e($a['username'])?></td><td><?=e($a['status'])?></td><td><?php if((int)$a['user_id']!==(int)current_user()['user_id']):?><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="user_id" value="<?=$a['user_id']?>"><button class="btn"><?=($a['status']==='Active')?'Deactivate':'Activate'?></button></form><?php else:?>Current account<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php page_footer();?>